class Solution {
public:
    int findMinDifference(vector<string>& timePoints) {
        if (timePoints.size() > 1440) return 0;
        bool seen[1440] = {};
        for (const string& tp : timePoints) {
            int minutes = (tp[0] - '0') * 600 + (tp[1] - '0') * 60 
                        + (tp[3] - '0') * 10 + (tp[4] - '0');
            if (seen[minutes]) return 0;
            seen[minutes] = true;
        }
        int minDiff = 1440;
        int first = -1, prev = -1;
        for (int i = 0; i < 1440; i++) {
            if (seen[i]) {
                if (first == -1) {
                    first = i;
                } else {
                    minDiff = min(minDiff, i - prev);
                }
                prev = i;
            }
        }
        minDiff = min(minDiff, 1440 - prev + first);
        return minDiff;
    }
};
